38	// Flow"). It returns the AssignAckCode the executor should reply with. A
39	// non-ACCEPTED code means the executor never subscribes to the c2e stream and
40	// Control is free to fall back before RequestStart.
41	//
42	// Precedence: an invalid request is rejected first, then draining, then
43	// unsupported mode, then capacity. Capacity is reserved by the caller only
44	// when this returns ASSIGN_ACK_ACCEPTED.
45	func EvaluateAssignment(req *strawpb.AssignRequest, capacity Capacity) strawpb.AssignAckCode {
46		if req == nil || req.Validate() != nil {
47			return strawpb.AssignAckCode_ASSIGN_ACK_REJECTED_ERROR
48		}
49	
50		if capacity.Draining {
51			return strawpb.AssignAckCode_ASSIGN_ACK_REJECTED_DRAINING
52		}
53	
54		if !capacity.supportsMode(req.GetMode()) {
55			return strawpb.AssignAckCode_ASSIGN_ACK_REJECTED_UNSUPPORTED
56		}
57	
58		if !capacity.hasCapacity() {
59			return strawpb.AssignAckCode_ASSIGN_ACK_REJECTED_CAPACITY
60		}
61	
62		return strawpb.AssignAckCode_ASSIGN_ACK_ACCEPTED
63	}
64	
65	// FakeExecutor is a deterministic stand-in for real outbound execution, used
66	// to drive lifecycle tests without any outbound HTTP. It emits a scripted
67	// sequence of e2c StreamFrames for an accepted assignment; the real outbound
68	// path (task 11) replaces the frame source but reuses the same sequencing.
69	type FakeExecutor struct {
