149	func (f *FakeExecutor) next(payload isPayload) *strawpb.StreamFrame {
150		f.seq++
151		frame := &strawpb.StreamFrame{StreamSeq: f.seq, Attempt: f.attempt}
152		payload.set(frame)
153	
154		return frame
