44	// Resolver is the DNS boundary Egress uses before validating resolved IPs.
45	type Resolver interface {
46		LookupIPAddr(ctx context.Context, host string) ([]net.IPAddr, error)
47	}
48	
49	// ExecutorOptions configures the P0 outbound executor.
50	type ExecutorOptions struct {
51		Resolver    Resolver
52		DialContext func(context.Context, string, string) (net.Conn, error)
53	}
54	
55	// Executor performs P0 decoded HTTP/HTTPS outbound execution.
56	type Executor struct {
57		resolver    Resolver
58		dialContext func(context.Context, string, string) (net.Conn, error)
59	}
60	
61	type defaultResolver struct{}
62	
63	func (defaultResolver) LookupIPAddr(ctx context.Context, host string) ([]net.IPAddr, error) {
64		ips, err := net.DefaultResolver.LookupIPAddr(ctx, host)
65		if err != nil {
66			return nil, fmt.Errorf("lookup IP %q: %w", host, err)
67		}
68	
69		return ips, nil
70	}
