72	// NewExecutor builds an executor with P0 transport defaults.
73	func NewExecutor(opts ExecutorOptions) *Executor {
74		resolver := opts.Resolver
75		if resolver == nil {
76			resolver = defaultResolver{}
77		}
78	
79		dialContext := opts.DialContext
80		if dialContext == nil {
81			dialContext = (&net.Dialer{}).DialContext
82		}
83	
84		return &Executor{resolver: resolver, dialContext: dialContext}
85	}
