87	// NewP0Transport returns the official P0 HTTP transport defaults: no HTTP/2
88	// and no upstream keep-alives.
89	func NewP0Transport(dialContext func(context.Context, string, string) (net.Conn, error)) *http.Transport {
90		if dialContext == nil {
91			dialContext = (&net.Dialer{}).DialContext
92		}
93	
94		return &http.Transport{
95			Proxy:             nil,
96			DialContext:       dialContext,
97			DisableKeepAlives: true,
98			ForceAttemptHTTP2: false,
99			TLSNextProto:      map[string]func(string, *tls.Conn) http.RoundTripper{},
100		}
101	}
