103	// Execute performs one outbound request from a Control-resolved RequestStart
104	// and returns the e2c stream frames for the attempt.
105	func (e *Executor) Execute(ctx context.Context, start *strawpb.RequestStart, body []byte, attempt uint32) []*strawpb.StreamFrame {
106		frames := newFrameBuilder(attempt)
107	
108		target, failure := parseTarget(start)
109		if failure != nil {
110			return []*strawpb.StreamFrame{frames.error(failure)}
111		}
112	
113		emit := []*strawpb.StreamFrame{frames.outboundStart(target.host, target.port)}
114	
115		failure = validateStart(start)
116		if failure != nil {
117			return append(emit, frames.error(failure))
118		}
119	
120		reqCtx, cancel := e.deadlineContext(ctx, start.GetDeadlineUnixMs())
121		defer cancel()
122	
123		err := reqCtx.Err()
124		if err != nil {
125			return append(emit, frames.error(timeoutFailure()))
126		}
127	
128		req, failure := buildHTTPRequest(reqCtx, start, body)
129		if failure != nil {
130			return append(emit, frames.error(failure))
131		}
132	
133		tr, client := e.httpClient(start.GetDestinationPolicy())
134		defer tr.CloseIdleConnections()
135	
136		resp, err := client.Do(req)
137		if err != nil {
138			return append(emit, frames.error(mapHTTPError(reqCtx, err)))
139		}
140		defer func() { _ = resp.Body.Close() }()
141	
142		status, failure := responseStatus(resp.StatusCode)
143		if failure != nil {
144			return append(emit, frames.error(failure))
145		}
146	
147		emit = append(emit, frames.responseStart(status, responseHeaders(resp.Header)))
148	
149		data, err := io.ReadAll(resp.Body)
150		if err != nil {
151			return append(emit, frames.error(mapHTTPError(reqCtx, err)))
152		}
153	
154		if len(data) > 0 {
155			emit = append(emit, frames.data(0, data))
156		}
157	
158		return append(emit, frames.end())
159	}
