161	func (e *Executor) httpClient(policy *strawpb.DestinationPolicy) (*http.Transport, *http.Client) {
162		tr := NewP0Transport(func(ctx context.Context, network, address string) (net.Conn, error) {
163			return e.dialValidated(ctx, network, address, policy)
164		})
165	
166		return tr, &http.Client{
167			Transport: tr,
168			CheckRedirect: func(*http.Request, []*http.Request) error {
169				return http.ErrUseLastResponse
170			},
171		}
172	}
173	
174	func (e *Executor) deadlineContext(ctx context.Context, deadlineUnixMs int64) (context.Context, context.CancelFunc) {
175		if deadlineUnixMs <= 0 {
176			return context.WithCancel(ctx)
177		}
178	
179		deadline := time.UnixMilli(deadlineUnixMs)
180		if existing, ok := ctx.Deadline(); ok && existing.Before(deadline) {
181			return context.WithCancel(ctx)
182		}
183	
184		return context.WithDeadline(ctx, deadline)
185	}
