187	func (e *Executor) dialValidated(ctx context.Context, network, address string, policy *strawpb.DestinationPolicy) (net.Conn, error) {
188		host, port, err := net.SplitHostPort(address)
189		if err != nil {
190			return nil, executorFailure(strawpb.ErrorCode_ERROR_CODE_EXECUTOR_INTERNAL_ERROR, invalidRequestStartFact)
191		}
192	
193		ips, err := e.resolver.LookupIPAddr(ctx, host)
194		if err != nil || len(ips) == 0 {
195			if errors.Is(ctx.Err(), context.DeadlineExceeded) {
196				return nil, timeoutFailure()
197			}
198	
199			return nil, executorFailure(strawpb.ErrorCode_ERROR_CODE_UPSTREAM_DNS_FAILURE, dnsNoRecordsFact)
200		}
201	
202		var selected netip.Addr
203	
204		for i, ip := range ips {
205			addr, ok := netIPAddr(ip)
206			if !ok {
207				return nil, executorFailure(strawpb.ErrorCode_ERROR_CODE_UPSTREAM_DNS_FAILURE, dnsNoRecordsFact)
208			}
209	
210			failure := validateResolvedIP(policy, addr)
211			if failure != nil {
212				return nil, failure
213			}
214	
215			if i == 0 {
216				selected = addr
217			}
218		}
219	
220		return e.dialContext(ctx, network, net.JoinHostPort(selected.String(), port))
221	}
