451	type executionError struct {
452		code        strawpb.ErrorCode
453		fact        string
454		timeoutType strawpb.TimeoutType
455	}
456	
457	func (e *executionError) Error() string {
458		return fmt.Sprintf("%s: %s", e.code, e.fact)
459	}
460	
461	func executorFailure(code strawpb.ErrorCode, fact string) *executionError {
462		return &executionError{code: code, fact: fact}
463	}
464	
465	func timeoutFailure() *executionError {
466		return &executionError{
467			code:        strawpb.ErrorCode_ERROR_CODE_TIMEOUT_EXCEEDED,
468			fact:        deadlineExceededFact,
469			timeoutType: strawpb.TimeoutType_TIMEOUT_TYPE_TOTAL_DEADLINE_TIMEOUT,
470		}
471	}
472	
473	func mapHTTPError(ctx context.Context, err error) *executionError {
474		var failure *executionError
475		if errors.As(err, &failure) {
476			return failure
477		}
478	
479		if errors.Is(ctx.Err(), context.DeadlineExceeded) || errors.Is(err, context.DeadlineExceeded) {
480			return timeoutFailure()
481		}
482	
483		if errors.Is(err, syscall.ECONNREFUSED) {
484			return executorFailure(strawpb.ErrorCode_ERROR_CODE_UPSTREAM_CONNECTION_REFUSED, tcpRefusedFact)
485		}
486	
487		if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
488			return executorFailure(strawpb.ErrorCode_ERROR_CODE_UPSTREAM_RESET, upstreamResetFact)
489		}
490	
491		if looksLikeTLSError(err) {
492			return executorFailure(strawpb.ErrorCode_ERROR_CODE_UPSTREAM_TLS_FAILURE, tlsHandshakeFailedFact)
493		}
494	
495		return executorFailure(strawpb.ErrorCode_ERROR_CODE_EXECUTOR_INTERNAL_ERROR, executorInternalFact)
496	}
497	
498	func looksLikeTLSError(err error) bool {
499		s := strings.ToLower(err.Error())
500	
501		return strings.Contains(s, "tls") || strings.Contains(s, "certificate")
502	}
503	
504	func netIPAddr(ip net.IPAddr) (netip.Addr, bool) {
505		if v4 := ip.IP.To4(); v4 != nil {
506			addr, ok := netip.AddrFromSlice(v4)
507	
508			return addr, ok
509		}
510	
511		addr, ok := netip.AddrFromSlice(ip.IP)
512	
513		return addr, ok
514	}
515	
516	func validateResolvedIP(policy *strawpb.DestinationPolicy, addr netip.Addr) *executionError {
517		if policy == nil {
518			return executorFailure(strawpb.ErrorCode_ERROR_CODE_EXECUTOR_INTERNAL_ERROR, invalidDestinationFact)
519		}
520	
521		if addr.Is4In6() {
522			return executorFailure(strawpb.ErrorCode_ERROR_CODE_DESTINATION_DENIED, dnsDeniedIPFact)
523		}
524	
525		failure := validateCIDRPolicy(policy, addr)
526		if failure != nil {
527			return failure
528		}
529	
530		if deniedByDefault(policy, addr) {
531			return executorFailure(strawpb.ErrorCode_ERROR_CODE_DESTINATION_DENIED, dnsDeniedIPFact)
532		}
533	
534		return nil
535	}
536	
537	func validateCIDRPolicy(policy *strawpb.DestinationPolicy, addr netip.Addr) *executionError {
538		allowed, failure := parsePrefixes(policy.GetAllowedCidrs())
539		if failure != nil {
540			return failure
541		}
542	
543		if len(allowed) > 0 && !prefixesContain(allowed, addr) {
544			return executorFailure(strawpb.ErrorCode_ERROR_CODE_DESTINATION_DENIED, dnsDeniedIPFact)
545		}
546	
547		denied, failure := parsePrefixes(policy.GetDeniedCidrs())
548		if failure != nil {
549			return failure
550		}
551	
552		if prefixesContain(denied, addr) {
553			return executorFailure(strawpb.ErrorCode_ERROR_CODE_DESTINATION_DENIED, dnsDeniedIPFact)
554		}
555	
556		return nil
557	}
558	
559	func deniedByDefault(policy *strawpb.DestinationPolicy, addr netip.Addr) bool {
560		if blockedUnless(policy.GetAllowMetadataIps(), isMetadataIP(addr)) {
561			return true
562		}
563	
564		if blockedUnless(policy.GetAllowLoopback(), addr.IsLoopback()) {
565			return true
566		}
567	
568		if blockedUnless(policy.GetAllowLinkLocal(), addr.IsLinkLocalUnicast()) {
569			return true
570		}
571	
572		if blockedUnless(policy.GetAllowMulticast(), addr.IsMulticast()) {
573			return true
574		}
575	
576		if blockedUnless(policy.GetAllowPrivateRanges(), addr.IsPrivate()) {
577			return true
578		}
579	
580		return prefixesContain(defaultDeniedPrefixes, addr)
581	}
582	
583	func blockedUnless(allowed bool, blocked bool) bool {
584		return blocked && !allowed
585	}
586	
587	func parsePrefixes(raw []string) ([]netip.Prefix, *executionError) {
588		prefixes := make([]netip.Prefix, 0, len(raw))
589		for _, s := range raw {
590			prefix, err := netip.ParsePrefix(s)
591			if err != nil {
592				return nil, executorFailure(strawpb.ErrorCode_ERROR_CODE_EXECUTOR_INTERNAL_ERROR, invalidDestinationFact)
593			}
594	
595			prefixes = append(prefixes, prefix)
596		}
597	
598		return prefixes, nil
599	}
600	
601	func prefixesContain(prefixes []netip.Prefix, addr netip.Addr) bool {
602		for _, prefix := range prefixes {
603			if prefix.Contains(addr) {
604				return true
605			}
606		}
607	
608		return false
609	}
610	
611	func isMetadataIP(addr netip.Addr) bool {
612		return slices.Contains(metadataIPs, addr)
613	}
614	
615	var metadataIPs = []netip.Addr{
616		netip.MustParseAddr("169.254.169.254"),
617		netip.MustParseAddr("169.254.169.253"),
618		netip.MustParseAddr("169.254.170.2"),
619		netip.MustParseAddr("100.100.100.200"),
620		netip.MustParseAddr("100.100.100.201"),
621	}
622	
623	var defaultDeniedPrefixes = []netip.Prefix{
624		netip.MustParsePrefix("0.0.0.0/8"),
625		netip.MustParsePrefix("100.64.0.0/10"),
626		netip.MustParsePrefix("192.0.0.0/24"),
627		netip.MustParsePrefix("192.0.2.0/24"),
628		netip.MustParsePrefix("192.88.99.0/24"),
629		netip.MustParsePrefix("198.18.0.0/15"),
630		netip.MustParsePrefix("198.51.100.0/24"),
631		netip.MustParsePrefix("203.0.113.0/24"),
632		netip.MustParsePrefix("240.0.0.0/4"),
633		netip.MustParsePrefix("255.255.255.255/32"),
634		netip.MustParsePrefix("::/128"),
635		netip.MustParsePrefix("64:ff9b::/96"),
636		netip.MustParsePrefix("100::/64"),
637		netip.MustParsePrefix("::ffff:0:0/96"),
638	}
639	
640	type frameBuilder struct {
641		attempt uint32
642		seq     uint64
643	}
644	
645	func newFrameBuilder(attempt uint32) *frameBuilder {
646		return &frameBuilder{attempt: attempt}
647	}
648	
649	func (b *frameBuilder) outboundStart(host string, port uint32) *strawpb.StreamFrame {
650		b.seq++
651	
652		return &strawpb.StreamFrame{
653			StreamSeq: b.seq,
654			Attempt:   b.attempt,
655			Payload: &strawpb.StreamFrame_OutboundStart{OutboundStart: &strawpb.OutboundStartFrame{
656				TargetHost:        host,
657				TargetPort:        port,
658				Attempt:           b.attempt,
659				WorkerTimestampMs: time.Now().UnixMilli(),
660			}},
661		}
662	}
663	
664	func responseStatus(status int) (uint32, *executionError) {
665		if status < 0 || status > 999 {
666			return 0, executorFailure(strawpb.ErrorCode_ERROR_CODE_EXECUTOR_INTERNAL_ERROR, executorInternalFact)
667		}
668	
669		return uint32(status), nil
670	}
671	
672	func (b *frameBuilder) responseStart(status uint32, headers []*strawpb.Header) *strawpb.StreamFrame {
673		b.seq++
674	
675		return &strawpb.StreamFrame{
676			StreamSeq: b.seq,
677			Attempt:   b.attempt,
678			Payload: &strawpb.StreamFrame_ResponseStart{ResponseStart: &strawpb.ResponseStart{
679				Status:  status,
680				Headers: headers,
681			}},
682		}
683	}
684	
685	func (b *frameBuilder) data(offset uint64, data []byte) *strawpb.StreamFrame {
686		b.seq++
687	
688		return &strawpb.StreamFrame{
689			StreamSeq: b.seq,
690			Attempt:   b.attempt,
691			Payload:   &strawpb.StreamFrame_Data{Data: &strawpb.DataFrame{Offset: offset, Data: data}},
692		}
693	}
694	
695	func (b *frameBuilder) end() *strawpb.StreamFrame {
696		b.seq++
697	
698		return &strawpb.StreamFrame{
699			StreamSeq: b.seq,
700			Attempt:   b.attempt,
701			Payload:   &strawpb.StreamFrame_End{End: &strawpb.EndFrame{Success: true}},
702		}
703	}
704	
705	func (b *frameBuilder) error(failure *executionError) *strawpb.StreamFrame {
706		errFrame := &strawpb.ErrorFrame{
707			Code:    failure.code,
708			Details: map[string]string{"fact": failure.fact},
709		}
710		if failure.timeoutType != strawpb.TimeoutType_TIMEOUT_TYPE_UNSPECIFIED {
711			errFrame.TimeoutType = &failure.timeoutType
712		}
713	
714		b.seq++
715	
716		return &strawpb.StreamFrame{
717			StreamSeq: b.seq,
718			Attempt:   b.attempt,
719			Payload:   &strawpb.StreamFrame_Error{Error: errFrame},
720		}
721	}
722

