// Package natsx contains NATS helpers for Straw services.
package natsx

import (
	"errors"
	"fmt"
	"strings"
	"unicode"
)

const payloadSafetyMargin = 64 * 1024

var (
	errUnsupportedStreamDirection = errors.New("unsupported stream direction")
	errMaxPayloadTooSmall         = errors.New("nats max payload must exceed safety margin")
	errFrameBodyLimitTooLarge     = errors.New("configured frame/body limit exceeds nats max payload")
	errNATSServersRequired        = errors.New("nats servers are required")
	errNATSServerEmpty            = errors.New("nats server is empty")
	errSubjectTokenRequired       = errors.New("subject token is required")
	errSubjectTokenUnsafe         = errors.New("subject token contains unsafe character")
)

// StreamDirection identifies the direction of a stream subject.
type StreamDirection string

const (
	// DirectionControlToExecutor marks control-to-executor stream subjects.
	DirectionControlToExecutor StreamDirection = "c2e"
	// DirectionExecutorToControl marks executor-to-control stream subjects.
	DirectionExecutorToControl StreamDirection = "e2c"
)

// RegistrationSubject returns the NATS subject for worker registration.
func RegistrationSubject() string {
	return "straw.v1.control.register"
}

// HeartbeatSubject returns the NATS subject for worker heartbeats.
func HeartbeatSubject() string {
	return "straw.v1.control.heartbeat"
}

// ControlInboxPrefix returns the reply-inbox prefix used by control clients.
func ControlInboxPrefix() string {
	return "_INBOX.ctl"
}

// WorkerInboxPrefix returns the worker-specific reply inbox prefix.
func WorkerInboxPrefix(workerID string) (string, error) {
	err := validateSubjectToken(workerID)
	if err != nil {
		return "", fmt.Errorf("worker_id: %w", err)
	}

	return "_INBOX.wrk." + workerID, nil
}

// ValidateSubjectToken reports whether token is a safe NATS subject token.
func ValidateSubjectToken(token string) error {
	return validateSubjectToken(token)
}

// AssignmentSubject returns the assignment subject for a worker session.
func AssignmentSubject(workerID, sessionID string) (string, error) {
	err := validateSubjectToken(workerID)
	if err != nil {
		return "", fmt.Errorf("worker_id: %w", err)
	}

	err = validateSubjectToken(sessionID)
	if err != nil {
		return "", fmt.Errorf("session_id: %w", err)
	}

	return fmt.Sprintf("straw.v1.executor.%s.%s.assign", workerID, sessionID), nil
}

// StreamSubject returns the stream subject for a request, worker, and session.
func StreamSubject(requestID, workerID, sessionID string, direction StreamDirection) (string, error) {
	err := validateSubjectToken(requestID)
	if err != nil {
		return "", fmt.Errorf("request_id: %w", err)
	}

	err = validateSubjectToken(workerID)
	if err != nil {
		return "", fmt.Errorf("worker_id: %w", err)
	}

	err = validateSubjectToken(sessionID)
	if err != nil {
		return "", fmt.Errorf("session_id: %w", err)
	}

	switch direction {
	case DirectionControlToExecutor, DirectionExecutorToControl:
		return fmt.Sprintf("straw.v1.req.%s.%s.%s.%s", requestID, workerID, sessionID, direction), nil
	default:
		return "", fmt.Errorf("%w: %q", errUnsupportedStreamDirection, direction)
	}
}

// TerminalSubject returns the terminal subject for a request stream.
func TerminalSubject(requestID, workerID, sessionID string, direction StreamDirection) (string, error) {
	return StreamSubject(requestID, workerID, sessionID, direction)
}

// ValidateMaxPayload checks the configured NATS payload limits.
func ValidateMaxPayload(maxPayloadBytes *uint64, maxFrameDataBytes, maxInlineRequestBodyBytes, maxInlineResponseBodyBytes uint64) error {
	if maxPayloadBytes == nil {
		return nil
	}

	if *maxPayloadBytes <= payloadSafetyMargin {
		return fmt.Errorf("%w: %d <= %d", errMaxPayloadTooSmall, *maxPayloadBytes, payloadSafetyMargin)
	}

	limit := max(maxInlineRequestBodyBytes, maxFrameDataBytes)

	limit = max(limit, maxInlineResponseBodyBytes)

	if limit > *maxPayloadBytes-payloadSafetyMargin {
		return fmt.Errorf("%w: %d > %d - %d safety margin", errFrameBodyLimitTooLarge, limit, *maxPayloadBytes, payloadSafetyMargin)
	}

	return nil
}

// ValidateServers validates the configured NATS server list.
func ValidateServers(servers []string) error {
	if len(servers) == 0 {
		return errNATSServersRequired
	}

	for i, server := range servers {
		if strings.TrimSpace(server) == "" {
			return fmt.Errorf("%w: %d", errNATSServerEmpty, i)
		}
	}

	return nil
}

func validateSubjectToken(token string) error {
	if token == "" {
		return errSubjectTokenRequired
	}

	for _, r := range token {
		switch {
		case unicode.IsLetter(r), unicode.IsDigit(r), r == '-', r == '_':
		default:
			return fmt.Errorf("%w: %q", errSubjectTokenUnsafe, r)
		}
	}

	return nil
}

package natsx

import (
	"time"

	strawpb "github.com/beremaran/straw/v2/api/proto/straw/v1"
)

// FrameOutcome is the result of validating one StreamFrame against a
// per-direction, per-attempt stream (docs/planning/12 "Stream Ordering and
// Sequencing"). Ignored/counted outcomes contribute to worker cooldown; the
// caller is responsible for that accounting.
type FrameOutcome int

const (
	// FrameAccepted means the frame was the next expected frame and was
	// applied to stream state.
	FrameAccepted FrameOutcome = iota
	// FrameDuplicate means stream_seq was lower than expected: ignored and
	// counted.
	FrameDuplicate
	// FrameAfterTerminal means a frame arrived after a terminal frame:
	// ignored and counted.
	FrameAfterTerminal
	// FrameSequenceGap means stream_seq was higher than expected: a protocol
	// error.
	FrameSequenceGap
	// FrameOffsetMismatch means a DataFrame offset did not equal the
	// cumulative bytes previously accepted: a protocol error.
	FrameOffsetMismatch
	// FrameCreditExhausted means a DataFrame carried more bytes than the
	// remaining granted credit: a protocol error.
	FrameCreditExhausted
	// FrameAttemptMismatch means the frame attempt did not equal the active
	// attempt: a protocol error.
	FrameAttemptMismatch
	// FrameInvalid means the frame was nil or carried no payload.
	FrameInvalid
)

// IsProtocolError reports whether the outcome is a hard protocol violation
// (as opposed to an ignored/counted duplicate or late frame).
func (o FrameOutcome) IsProtocolError() bool {
	return o == FrameSequenceGap || o == FrameOffsetMismatch || o == FrameCreditExhausted || o == FrameAttemptMismatch || o == FrameInvalid
}

// StreamValidator enforces the ordering, offset, credit, and terminal rules
// for a single stream direction and attempt (docs/planning/12). A validator
// models the receiving side of one byte stream: it holds the data-byte credit
// it has granted to the sender and rejects DataFrames that exceed it.
//
// stream_seq starts at 1 for each (attempt, direction). Credit applies only to
// DataFrame payload bytes; control and terminal frames never consume credit.
type StreamValidator struct {
	attempt      uint32
	expectedSeq  uint64
	offset       uint64
	credit       uint64
	terminal     bool
	idleTimeout  time.Duration
	lastActivity time.Time
	now          func() time.Time
}

// NewStreamValidator builds a validator for the given active attempt.
// initialCredit is the data-byte credit initially granted to the sender
// (AssignRequest initial upload/download credit). idleTimeout of zero disables
// the idle check. now may be nil (defaults to time.Now).
func NewStreamValidator(attempt uint32, initialCredit uint64, idleTimeout time.Duration, now func() time.Time) *StreamValidator {
	if now == nil {
		now = time.Now
	}

	return &StreamValidator{
		attempt:      attempt,
		expectedSeq:  1,
		credit:       initialCredit,
		idleTimeout:  idleTimeout,
		lastActivity: now(),
		now:          now,
	}
}

// GrantCredit adds data-byte credit for the sender (the receiver calls this
// when it emits a CreditFrame on the reverse channel after releasing buffered
// bytes).
func (v *StreamValidator) GrantCredit(bytes uint64) {
	v.credit += bytes
}

// Terminated reports whether a terminal frame has been accepted.
func (v *StreamValidator) Terminated() bool { return v.terminal }

// ExpectedSeq returns the next stream_seq the validator will accept.
func (v *StreamValidator) ExpectedSeq() uint64 { return v.expectedSeq }

// RemainingCredit returns the data-byte credit still available to the sender.
func (v *StreamValidator) RemainingCredit() uint64 { return v.credit }

// Accept validates f and, on FrameAccepted, advances stream state. All other
// outcomes leave state unchanged.
func (v *StreamValidator) Accept(f *strawpb.StreamFrame) FrameOutcome {
	if outcome := v.validateFrameShell(f); outcome != FrameAccepted {
		return outcome
	}

	seq := f.GetStreamSeq()
	switch {
	case seq < v.expectedSeq:
		return FrameDuplicate
	case seq > v.expectedSeq:
		return FrameSequenceGap
	}

	// stream_seq is exactly the next expected value. Apply payload-specific
	// validation before committing.
	if outcome := validateP0Payload(f); outcome != FrameAccepted {
		return outcome
	}

	if outcome := v.acceptData(f.GetData()); outcome != FrameAccepted {
		return outcome
	}

	v.expectedSeq++

	v.lastActivity = v.now()
	if isTerminalFrame(f) {
		v.terminal = true
	}

	return FrameAccepted
}

// IdleExpired reports whether the frame idle timeout has elapsed since the
// last accepted frame. It is never true once the stream is terminated.
func (v *StreamValidator) IdleExpired() bool {
	if v.idleTimeout <= 0 || v.terminal {
		return false
	}

	return v.now().Sub(v.lastActivity) >= v.idleTimeout
}

func (v *StreamValidator) validateFrameShell(f *strawpb.StreamFrame) FrameOutcome {
	if f == nil || f.GetPayload() == nil {
		return FrameInvalid
	}

	if v.terminal {
		return FrameAfterTerminal
	}

	if f.GetStreamSeq() == 0 {
		return FrameInvalid
	}

	if f.GetAttempt() != v.attempt {
		return FrameAttemptMismatch
	}

	return FrameAccepted
}

func validateP0Payload(f *strawpb.StreamFrame) FrameOutcome {
	if _, ok := f.GetPayload().(*strawpb.StreamFrame_BodyRef); ok {
		return FrameInvalid
	}

	return FrameAccepted
}

func (v *StreamValidator) acceptData(data *strawpb.DataFrame) FrameOutcome {
	if data == nil {
		return FrameAccepted
	}

	if data.GetOffset() != v.offset {
		return FrameOffsetMismatch
	}

	n := uint64(len(data.GetData()))
	if n > v.credit {
		return FrameCreditExhausted
	}

	v.credit -= n
	v.offset += n

	return FrameAccepted
}

// isTerminalFrame reports whether f carries a terminal payload (EndFrame,
// ErrorFrame, or CancelledFrame) per docs/planning/09 "Terminal Rule".
func isTerminalFrame(f *strawpb.StreamFrame) bool {
	switch f.GetPayload().(type) {
	case *strawpb.StreamFrame_End, *strawpb.StreamFrame_Error, *strawpb.StreamFrame_Cancelled:
		return true
	default:
		return false
	}
}

