	}

	req := env.GetAssignRequest()

	code := EvaluateAssignment(req, w.snapshotCapacity())
	if code != strawpb.AssignAckCode_ASSIGN_ACK_ACCEPTED {
		w.reply(msg, env, &strawpb.AssignAck{Code: code})

