func (w *Worker) snapshotCapacity() Capacity {
	w.mu.Lock()
	defer w.mu.Unlock()

	return Capacity{
		Draining:       w.draining,
		ActiveRequests: w.active,
		MaxConcurrency: w.maxConcurrency,
		SupportedModes: p0SupportedModes,
	}
}

func (w *Worker) reserve(requestID string, cancel context.CancelFunc) {
	w.mu.Lock()
	defer w.mu.Unlock()

