func requestContext(deadlineUnixMs int64) (context.Context, context.CancelFunc) {
	if deadlineUnixMs <= 0 {
		return context.WithCancel(context.Background())
	}

	return context.WithDeadline(context.Background(), time.UnixMilli(deadlineUnixMs))
