	go func() {
		resultCh <- w.executor.Execute(reqCtx, start, body, req.GetAttempt())
	}()

	result, canceled, reason := waitForResult(resultCh, frames, validator, cancel)
	if canceled {
		result = applyCancellation(result, reason)
	}

	w.publish(e2cSubject, env, result)
