				// Download credit grant for e2c response bytes. P0 executes
				// the whole response in one pass (Executor.Execute) rather
				// than chunking by credit; response buffering per credit is
				// Control's responsibility (docs/tasks/p0/24).
			default:
				return nil, nil, false
			}
		case <-ticker.C:
			if validator.IdleExpired() {
				return nil, nil, false
			}
		}
	}

	return start, body, true
}

// waitForResult waits for the outbound execution to finish while still
// accepting c2e frames, most importantly a CancelFrame, which cancels
// execCtx so Executor.Execute aborts promptly.
func waitForResult(resultCh <-chan []*strawpb.StreamFrame, frames <-chan *strawpb.StreamFrame, validator *natsx.StreamValidator, cancel context.CancelFunc) ([]*strawpb.StreamFrame, bool, string) {
	for {
		select {
		case result := <-resultCh:
			return result, false, ""
		case frame, ok := <-frames:
			if !ok {
				continue
			}

			if validator.Accept(frame) != natsx.FrameAccepted {
