		reply.TenantId = env.GetTenantId()
		reply.TraceId = env.GetTraceId()
		reply.DeadlineUnixMs = env.GetDeadlineUnixMs()
		reply.Attempt = env.GetAttempt()
	}

	raw, err := natsx.MarshalEnvelope(reply)
	if err != nil {
		return
	}

	_ = msg.Respond(raw)
}

