// Run keeps the worker registered and heartbeating, and runs the live
// assignment execution loop, until ctx is canceled. On shutdown it sends a
// draining heartbeat before telling the assignment loop to stop accepting
// new work and drain in-flight requests (docs/planning/29 "Worker Graceful
// Shutdown").
func Run(ctx context.Context, conn *natsx.Connection, id Identity, caps Capabilities, executor *Executor, heartbeatInterval time.Duration) error {
	if heartbeatInterval <= 0 {
		heartbeatInterval = defaultHeartbeatInterval
	}

	sessionID, err := Register(ctx, conn, id, caps)
	if err != nil {
		return err
	}

	worker, err := NewWorker(conn, id, executor, sessionID, caps.MaxConcurrency)
	if err != nil {
		return err
	}

	serveCtx, stopServing := context.WithCancel(context.Background())
	defer stopServing()

	serveDone := make(chan error, 1)

	go func() { serveDone <- worker.Serve(serveCtx) }()

	active := worker.ActiveRequests()

	err = Heartbeat(ctx, conn, id, sessionID, strawpb.WorkerHealth_WORKER_HEALTH_READY, active, capacityFromConcurrency(active, caps.MaxConcurrency), caps.MaxConcurrency, false)
	if err != nil {
		stopServing()
		<-serveDone

		return err
	}

	ticker := time.NewTicker(heartbeatInterval)
	defer ticker.Stop()

	for {
		select {

// (docs/planning/29 "Worker Graceful Shutdown", steps 2-3).
func (w *Worker) Serve(ctx context.Context) error {
	subject, err := natsx.AssignmentSubject(w.id.WorkerID, w.sessionID)
	if err != nil {
		return fmt.Errorf("assignment subject: %w", err)
	}

	sub, err := w.conn.Subscribe(subject, w.handleAssign)
	if err != nil {
		return fmt.Errorf("subscribe assignment: %w", err)
	}

	err = w.conn.Flush()
	if err != nil {
		_ = sub.Unsubscribe()

		return fmt.Errorf("flush assignment subscription: %w", err)
	}

	<-ctx.Done()

	w.mu.Lock()
	w.draining = true
	w.mu.Unlock()

	_ = sub.Unsubscribe()

	drained := make(chan struct{})

	go func() {
		w.wg.Wait()
		close(drained)
	}()

	select {
	case <-drained:
	case <-time.After(workerDrainTimeout):
		w.abandonInFlight()
		<-drained
	}

	return nil
}

func (w *Worker) abandonInFlight() {
	w.mu.Lock()
